        p0 = add_2d_ptr(p0, off0, size0, c0, inc0);
        r0[16] = (int32_t)(uintptr_t)p0; r0[17] = c0; r0[18] = 0; r0[19] = (int32_t)(uintptr_t)bp0;
        r0[20] = r0[21] = r0[22] = r0[23] = 0;
